from model import Summary,Event,Kind
def run(events, initial):
 balance = initial
 rejected = 0
 peak = initial
 locked = False
 audit = []

 for event in events:
  if event.kind == Kind.CREDIT:
   if 0 <= event.amount <= 1000000:
    balance += event.amount
   else:
    rejected += 1
  elif event.kind == Kind.DEBIT:
   if not 0 <= event.amount <= 1000000 or locked or event.amount > balance:
    rejected += 1
   else:
    balance -= event.amount
  elif event.kind == Kind.LOCK:
   locked = True
  elif event.kind == Kind.UNLOCK:
   locked = False

  peak = max(peak, balance)
  audit.append(balance)

 return Summary(balance, rejected, peak, audit)
